import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from sklearn.preprocessing import StandardScaler

MAX_DRIVERS = 3

def design(feats):
    # Identify strongest features by mean difference
    means = [np.mean(feats.y[feats.x[:, feats.column(fid)] > 0]) for fid in feats.ids]
    diffs = [means[i] - np.mean(feats.y) for i, fid in enumerate(feats.ids)]

    # Sort by absolute difference
    sorted_idx = np.argsort(np.abs(diffs))[::-1]

    # Select top candidates
    candidates = [feats.ids[i] for i in sorted_idx[:20]]

    # Remove near-duplicates
    keep = []
    for fid in candidates:
        is_duplicate = False
        for kept_fid in keep:
            if abs(np.corrcoef(feats.x[:, feats.column(fid)], 
                              feats.x[:, feats.column(kept_fid)])[0,1]) > 0.6:
                is_duplicate = True
                break
        if not is_duplicate:
            keep.append(fid)

    # Check for interaction terms among top candidates
    best_features = keep[:5]
    products = []

    # Look for significant interactions
    for i, a in enumerate(best_features):
        for b in best_features[i+1:]:
            # Create interaction term
            x_a = feats.x[:, feats.column(a)]
            x_b = feats.x[:, feats.column(b)]
            prod = x_a * x_b

            # Test significance using t-test
            y1 = prod[feats.y == 1]
            y0 = prod[feats.y == 0]

            if len(y1) > 0 and len(y0) > 0:
                t_stat, _ = stats.ttest_ind(y1, y0)
                if abs(t_stat) > 2.0:
                    products.append((a, b))

    # If we have strong interactions, return them
    if products:
        return Design(
            drivers=(products[0][0],),
            columns=(products[0][0], products[0][1]),
            products=products,
            loadings={products[0][0]: 1.0, products[0][1]: 1.0}
        )

    # Otherwise, return top individual feature
    if best_features:
        return Design(
            drivers=(best_features[0],),
            columns=(best_features[0],),
            products=(),
            loadings={best_features[0]: 1.0}
        )

    # No mechanism found
    return Design(drivers=(), columns=(), products=(), loadings={})

